    #[test]
    fn released_window_backings_do_not_exhaust_native_slots() {
        let manager =
            ethornell_archive::ResourceManager::open_game(env!("CARGO_MANIFEST_DIR")).unwrap();
        let mut api = super::RuntimeTraceApi::new(manager);
        let bitmap = 1900;
        let source_key = "test:window-backing-source";
        api.store_graph_image(
            source_key.to_string(),
            DecodedImage {
                width: 8,
                height: 8,
                rgba: vec![255; 8 * 8 * 4],
            },
        );
        api.graph_resources
            .insert(bitmap, RuntimeGraphResource::whole(source_key.to_string()));

        // Repeated dialogue/menu lifetimes must reuse the same native slot,
        // while the independent source bitmap remains available.
        for _ in 0..32 {
            let window = api.alloc_window_surface(8, 8).expect("free Window slot");
            assert_eq!(window, 0xB000_0000_u32 as i32);
            assert!(api.retain_surface_backing(window, bitmap));
            let backing_key = api.graph_resources[&window].key.clone();
            let mut release = vec![Value::Int(window)];
            call_graph(&mut api, 0x90, 0x81, &mut release).unwrap();
            assert!(!api.graph_handle_exists(window));
            assert!(!api.graph_images.contains_key(&backing_key));
            assert!(!api.graph_image_revisions.contains_key(&backing_key));
            assert!(api.graph_images.contains_key(source_key));
            assert!(api.graph_resources.contains_key(&bitmap));
        }
    }

    #[test]
    fn slash_resource_names_are_synthesized_like_dcprocimagesynth() {
        let manager =
            ethornell_archive::ResourceManager::open_game(env!("CARGO_MANIFEST_DIR")).unwrap();
        let mut api = super::RuntimeTraceApi::new(manager);
        let image = |rgba: [u8; 4], width: u32| DecodedImage {
            width,
            height: 1,
            rgba: rgba.repeat(width as usize),
        };
        api.store_graph_image("a:base".into(), image([10, 20, 30, 255], 3));
        api.graph_image_formats.insert("a:base".into(), 1);
        api.store_graph_image("a:top".into(), image([200, 100, 50, 255], 1));
        api.graph_image_formats.insert("a:top".into(), 2);
        // Element "top" at (1, 0) with mode 0 + 0x20 and parameter 0: an
        // opaque ARGB pixel copied over the RGB base.
        assert!(api.load_graph_image_resource(7, "a", "base/top,1,0,0,0"));
        let result = api.graph_bitmap_image(7).unwrap();
        assert_eq!(&result.rgba[0..3], &[10, 20, 30]);
        assert_eq!(&result.rgba[4..7], &[200, 100, 50]);
        assert_eq!(&result.rgba[8..11], &[10, 20, 30]);
        assert_eq!(api.bitmap_formats[&7], 1);
    }

    #[test]
    fn synchronous_load_window_follows_sub_402080() {
        let manager =
            ethornell_archive::ResourceManager::open_game(env!("CARGO_MANIFEST_DIR")).unwrap();
        let mut api = super::RuntimeTraceApi::new(manager);
        // Without a hold and without the configured gate every load yields.
        assert!(!api.graph_sync_load_active());
        api.graph_config.sync_load_hold_ms = 100;
        api.engine_time_ms = 1000;
        // The first load opens the window, later ones stay inside it.
        assert!(api.graph_sync_load_active());
        api.engine_time_ms = 1099;
        assert!(api.graph_sync_load_active());
        // Once it has passed, one load yields and the window resets.
        api.engine_time_ms = 1100;
        assert!(!api.graph_sync_load_active());
        assert!(api.graph_sync_load_active());
    }

    #[test]
    fn graph90_51_refuses_attached_or_missing_sprites() {
        let manager =
            ethornell_archive::ResourceManager::open_game(env!("CARGO_MANIFEST_DIR")).unwrap();
        let mut api = super::RuntimeTraceApi::new(manager);
        let Value::Int(sprite) = call_graph(&mut api, 0x90, 0x50, &mut Vec::new()).unwrap() else {
            panic!("sprite creation did not return a handle");
        };
        // Attached as a child (+0x11C parent): sub_47C110 reports an error.
        api.graph_native_owners.insert(sprite, 0x7000_0001);
        assert!(call_graph(&mut api, 0x90, 0x51, &mut vec![Value::Int(sprite)]).is_err());
        api.graph_native_owners.remove(&sprite);
        call_graph(&mut api, 0x90, 0x51, &mut vec![Value::Int(sprite)]).unwrap();
        // The slot is gone: releasing it again is an error too.
        assert!(call_graph(&mut api, 0x90, 0x51, &mut vec![Value::Int(sprite)]).is_err());
    }

