    #[test]
    fn graph92_1e_draws_one_bit_cells_and_raises_the_target_errors() {
        let manager =
            ethornell_archive::ResourceManager::open_game(env!("CARGO_MANIFEST_DIR")).unwrap();
        let mut api = super::RuntimeTraceApi::new(manager);
        let mut create = vec![Value::Int(5), Value::Int(64), Value::Int(16), Value::Int(1)];
        call_graph(&mut api, 0x90, 0x11, &mut create).unwrap();
        let draw = |api: &mut super::RuntimeTraceApi, bitmap: i32, font: i32, size: i32| {
            let mut stack = vec![
                Value::Int(bitmap),
                Value::Int(0),
                Value::Int(0),
                Value::Str("■a".into()),
                Value::Int(font),
                Value::Int(size),
                Value::Int(0),
                Value::Int(2),
                Value::Int(0xFF0000),
            ];
            call_graph(api, 0x92, 0x1E, &mut stack)
        };
        // Full cell 12 + half cell 6, each followed by the spacing.
        assert_eq!(
            draw(&mut api, 5, 0, 12).unwrap(),
            Value::Int(12 + 2 + 6 + 2)
        );
        let image = api.graph_bitmap_image(5).unwrap();
        let colors = image
            .rgba
            .as_chunks::<4>()
            .0
            .iter()
            .copied()
            .collect::<std::collections::BTreeSet<_>>();
        // Ink is the packed colour with no antialiased intermediate tones;
        // the format-1 fourth byte keeps its value (0).
        assert_eq!(colors, [[0, 0, 0, 0], [255, 0, 0, 0]].into());
        {
            // Nothing is drawn below the cell height.
            assert!((12..16).all(|row| {
                (0..64).all(|col| image.rgba[((row * 64 + col) * 4) as usize] == 0)
            }));
        }
        assert!(draw(&mut api, 0x4000, 0, 12).is_err());
        assert!(draw(&mut api, 6, 0, 12).is_err());
        assert!(draw(&mut api, 5, 99, 12).is_err());
        assert!(draw(&mut api, 5, 1, 7).is_err());
        assert!(draw(&mut api, 5, 1, 201).is_err());
        assert!(draw(&mut api, 5, 1, 200).is_ok());
    }

    #[test]
    fn bitmap_pixel_bridge_uses_target_dib_byte_order_per_format() {
        let manager =
            ethornell_archive::ResourceManager::open_game(env!("CARGO_MANIFEST_DIR")).unwrap();
        let mut api = super::RuntimeTraceApi::new(manager);
        // sub_4080B0 packs format-1 bytes as B,G,R into XRGB dwords.
        assert!(api.create_bitmap_from_rgb(10, 2, 1, 1, &[1, 2, 3, 4, 5, 6]));
        let image = api.graph_bitmap_image(10).unwrap();
        assert_eq!(image.rgba, [3, 2, 1, 255, 6, 5, 4, 255]);
        assert_eq!(api.bitmap_formats[&10], 1);
        // sub_408200 copies three bytes per format-1 pixel and rejects a
        // buffer that is too small.
        assert_eq!(api.read_bitmap_pixels(10, 5), None);
        assert_eq!(api.read_bitmap_pixels(10, 6), Some(vec![1, 2, 3, 4, 5, 6]));
        // Format 2 keeps alpha in the fourth byte.
        assert!(api.create_bitmap_from_rgb(11, 1, 1, 2, &[1, 2, 3, 0x80]));
        assert_eq!(api.graph_bitmap_image(11).unwrap().rgba, [3, 2, 1, 0x80]);
        assert_eq!(api.read_bitmap_pixels(11, 4), Some(vec![1, 2, 3, 0x80]));
    }

    #[test]
    fn native_graph_scheduler_and_work_bitmap_follow_validated_configuration() {
        let manager =
            ethornell_archive::ResourceManager::open_game(env!("CARGO_MANIFEST_DIR")).unwrap();
        let mut api = super::RuntimeTraceApi::new(manager);

        let mut scheduler = vec![Value::Int(0)];
        call_graph(&mut api, 0x90, 0x01, &mut scheduler).unwrap();
        assert!(!api.graph_scheduler_enabled);

        let mut frame_rate = vec![Value::Int(1000)];
        call_graph(&mut api, 0x90, 0x02, &mut frame_rate).unwrap();
        assert_eq!(api.graph_frame_rate, 1000);
        let mut invalid_frame_rate = vec![Value::Int(1001)];
        call_graph(&mut api, 0x90, 0x02, &mut invalid_frame_rate).unwrap();
        assert_eq!(api.graph_frame_rate, 1000);

        let mut memory_limit = vec![Value::Int(0x2000_0000)];
        call_graph(&mut api, 0x90, 0x03, &mut memory_limit).unwrap();
        assert_eq!(api.graph_memory_limit, 0x2000_0000);
        let mut invalid_memory_limit = vec![Value::Int(0x2000_0001)];
        call_graph(&mut api, 0x90, 0x03, &mut invalid_memory_limit).unwrap();
        assert_eq!(api.graph_memory_limit, 0x2000_0000);

        let bitmap = 3790;
        let mut create = vec![Value::Int(bitmap)];
        call_graph(&mut api, 0x90, 0x04, &mut create).unwrap();
        assert_eq!(api.bitmap_dimensions[&bitmap], (1280, 720));
        assert_eq!(api.bitmap_formats[&bitmap], 1);
        assert_eq!(api.graph_surfaces[&bitmap].width, 1280.0);
        assert_eq!(api.graph_surfaces[&bitmap].height, 720.0);
        assert!(!api.graph_config.bitmap_priorities.contains_key(&bitmap));

        let prioritized = 3791;
        let mut create_prioritized = vec![Value::Int(prioritized), Value::Int(1791)];
        call_graph(&mut api, 0x90, 0x05, &mut create_prioritized).unwrap();
        assert_eq!(api.bitmap_dimensions[&prioritized], (1280, 720));
        assert_eq!(api.graph_config.bitmap_priorities[&prioritized], 1791);
        let captured = &api.graph_resources[&prioritized];
        assert_eq!(
            captured.key,
            format!("runtime:priority-bitmap:{prioritized}")
        );
        assert_eq!(
            api.graph_surfaces[&prioritized].resource_id,
            Some(prioritized)
        );

        let mut dirty = vec![Value::Int(0)];
        call_graph(&mut api, 0x90, 0x00, &mut dirty).unwrap();
        assert_eq!(api.graph_redraw_requested, Some(false));
        let mut full = vec![Value::Int(1)];
        call_graph(&mut api, 0x90, 0x00, &mut full).unwrap();
        assert_eq!(api.graph_redraw_requested, Some(true));
        let mut dirty_after_full = vec![Value::Int(0)];
        call_graph(&mut api, 0x90, 0x00, &mut dirty_after_full).unwrap();
        assert_eq!(api.graph_redraw_requested, Some(true));
    }

